// Public "run a fresh discovery cycle" page.
// Nothing starts automatically: one POST per button press, with a request UUID
// generated by crypto and kept in sessionStorage so a retry or reload reuses it
// and an accepted job is resumed by polling, never re-posted. Status is polled
// every 4 s (no SSE). The result is fetched only once the server reports
// "completed" and is rendered only if sdk.status is "completed" and
// verification.status is "passed". All server text goes through textContent;
// missing values render "—" rather than an invented number.
(() => {
  'use strict';
  const CONFIG_URL = './data/discovery-endpoint.json';
  const STORE_KEY = 'wafflebench.discoveryRun.v1';
  const POLL_MS = 4000;
  const MAX_BACKOFF_MS = 30000;
  const FETCH_TIMEOUT_MS = 15000;
  const RESULT_RETRIES = 6;
  const MAX_VALUE_ROWS = 400;
  const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const LOOPBACK = new Set(['localhost', '127.0.0.1', '[::1]']);
  const $ = id => document.getElementById(id);
  const state = {origin:null, busy:false, timer:null, failures:0, resultTries:0, startedHere:false, bytes:null, jobId:null, memStore:null, recheck:null};

  // ---------- null-safe helpers ----------
  const finite = v => typeof v === 'number' && Number.isFinite(v);
  const arr = v => Array.isArray(v) ? v : [];
  const obj = v => v && typeof v === 'object' && !Array.isArray(v) ? v : null;
  const str = v => typeof v === 'string' && v.trim() ? v : null;
  const show = v => v == null || v === '' ? '—' : String(v);
  const clip = (s, n = 300) => s.length > n ? `${s.slice(0, n)}…` : s;
  const time = iso => { const t = Date.parse(iso); return Number.isFinite(t) ? new Date(t).toISOString().replace('T', ' ').replace(/\.\d+Z$/, ' UTC') : show(iso); };
  const json = v => { try { return JSON.stringify(v, null, 2) ?? '—'; } catch { return '—'; } };
  const count = v => finite(v) ? String(v) : Array.isArray(v) ? String(v.length) : '—';
  const escapeRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  function h(tag, props, ...kids) {
    const el = document.createElement(tag);
    for (const [k, v] of Object.entries(props || {})) {
      if (v == null || v === false) continue;
      if (k === 'class') el.className = v;
      else if (k === 'text') el.textContent = v;
      else el.setAttribute(k, v === true ? '' : v);
    }
    for (const kid of kids.flat(Infinity)) {
      if (kid == null || kid === false) continue;
      el.append(kid instanceof Node ? kid : document.createTextNode(String(kid)));
    }
    return el;
  }
  const code = v => h('code', {class:'mono-id'}, show(v));
  const meta = rows => rows.map(([k, v]) => h('div', null, h('dt', null, k), h('dd', null, v instanceof Node ? v : show(v))));
  const receipt = rows => h('dl', {class:'receipt'}, meta(rows));
  const mark = ok => ok == null ? h('span', null, '—') : h('span', {class: ok ? 'ok' : 'bad'}, ok ? 'match' : 'mismatch');
  const who = (kind, text) => h('span', {class:`who ${kind}`}, text);

  // ---------- session storage (per tab) ----------
  function readStore() {
    try {
      const v = obj(JSON.parse(sessionStorage.getItem(STORE_KEY) || 'null'));
      if (v && UUID_RE.test(v.request_id || '') && (v.job_id == null || UUID_RE.test(v.job_id))) return v;
    } catch { /* storage blocked or corrupt */ }
    return state.memStore;
  }
  function writeStore(v) {
    state.memStore = v;
    try { sessionStorage.setItem(STORE_KEY, JSON.stringify(v)); return true; } catch { return false; }
  }
  function clearStore() {
    state.memStore = null;
    try { sessionStorage.removeItem(STORE_KEY); } catch { /* ignore */ }
  }
  function newUuid() {
    const c = globalThis.crypto;
    if (c && typeof c.randomUUID === 'function') return c.randomUUID();
    if (!c || typeof c.getRandomValues !== 'function') return null;
    const b = c.getRandomValues(new Uint8Array(16));
    b[6] = (b[6] & 0x0f) | 0x40; b[8] = (b[8] & 0x3f) | 0x80;
    const x = [...b].map(n => n.toString(16).padStart(2, '0')).join('');
    return `${x.slice(0, 8)}-${x.slice(8, 12)}-${x.slice(12, 16)}-${x.slice(16, 20)}-${x.slice(20)}`;
  }

  // ---------- config ----------
  // Only an origin is accepted: https without userinfo/path/query/fragment, or
  // plain http to a loopback host when this page itself is served from loopback.
  function parseConfig(raw) {
    const c = obj(raw);
    if (!c) return {kind:'invalid', reason:'The run configuration is not a JSON object.'};
    if (Object.keys(c).some(k => k !== 'api_base' && k !== 'enabled')) return {kind:'invalid', reason:'The run configuration contains unexpected fields.'};
    if (c.enabled !== true) return {kind:'disabled'};
    if (!str(c.api_base)) return {kind:'invalid', reason:'Live runs are enabled but no API origin is configured.'};
    let u;
    try { u = new URL(c.api_base.trim()); } catch { return {kind:'invalid', reason:'The configured API origin is not a valid URL.'}; }
    if (u.username || u.password) return {kind:'invalid', reason:'The configured API origin must not contain credentials.'};
    if ((u.pathname !== '/' && u.pathname !== '') || u.search || u.hash || /[?#]/.test(c.api_base)) return {kind:'invalid', reason:'The configured API origin must be a bare origin without a path, query or fragment.'};
    const pageLoopback = LOOPBACK.has(location.hostname);
    if (u.protocol === 'https:') return {kind:'ok', origin:u.origin};
    if (u.protocol === 'http:' && LOOPBACK.has(u.hostname) && pageLoopback) return {kind:'ok', origin:u.origin};
    return {kind:'invalid', reason: u.protocol === 'http:' && LOOPBACK.has(u.hostname) ? 'A loopback http origin is accepted only when this page is opened from localhost.' : 'The configured API origin must use https.'};
  }

  // ---------- network ----------
  async function request(path, method = 'GET', body) {
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), FETCH_TIMEOUT_MS);
    try {
      const res = await fetch(state.origin + path, {
        method, body, signal:ctl.signal, mode:'cors', credentials:'omit', cache:'no-store', redirect:'error', referrerPolicy:'no-referrer',
        headers: body ? {'Content-Type':'application/json'} : undefined,
      });
      const bytes = await res.arrayBuffer();
      let data = null;
      try { data = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(bytes)); } catch { /* non-JSON body */ }
      return {ok:true, status:res.status, data, bytes, retryAfter:res.headers.get('Retry-After')};
    } catch (error) {
      return {ok:false, timeout: error?.name === 'AbortError'};
    } finally { clearTimeout(t); }
  }
  const serverMessage = d => { const o = obj(d); const m = o && (str(o.message) || str(o.error) || str(o.detail)); return m ? clip(m) : null; };
  const withMessage = (text, d) => { const m = serverMessage(d); return m ? `${text} Server message: “${m}”` : text; };
  const retryAfterText = v => /^\d+$/.test(v || '') ? ` Retry after about ${Math.ceil(Number(v) / 60)} min.` : '';

  // ---------- UI state ----------
  function setState(kind, badge, text) {
    const b = $('stateBadge'), t = $('stateText');
    if (b.dataset.kind !== kind) b.dataset.kind = kind;
    if (b.textContent !== badge) b.textContent = badge;
    if (t.textContent !== text) t.textContent = text;
  }
  function setReason(text, problem = false) {
    const r = $('runReason');
    r.textContent = text;
    r.classList.toggle('is-problem', problem);
  }
  function controls({start = false, startLabel = 'Start new research loop', recheck = null, newRun = false} = {}) {
    $('startRun').disabled = !start;
    $('startRun').textContent = startLabel;
    state.recheck = recheck;
    $('recheck').hidden = !recheck;
    $('newRun').hidden = !newRun;
  }
  function schedule(fn, ms) { clearTimeout(state.timer); state.timer = setTimeout(fn, ms); }

  // ---------- init / health ----------
  async function init() {
    let raw;
    try {
      const res = await fetch(CONFIG_URL, {cache:'no-store'});
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      raw = await res.json();
    } catch (error) {
      console.error('Discovery run config:', error);
      setState('error', 'Unavailable', 'Live runs are unavailable.');
      setReason('The run configuration could not be read. You can still read the recorded cycle.', true);
      return controls({recheck: init});
    }
    const cfg = parseConfig(raw);
    if (cfg.kind === 'disabled') {
      setState('idle', 'Disabled', 'Live runs are not enabled on this deployment.');
      setReason('The run button is switched off here. The recorded, verified cycle is available on the Recorded cycle page.');
      $('serviceMeta').replaceChildren(...meta([['Run service', 'not enabled']]));
      return controls();
    }
    if (cfg.kind !== 'ok') {
      setState('error', 'Misconfigured', 'Live runs are unavailable.');
      setReason(cfg.reason, true);
      return controls();
    }
    state.origin = cfg.origin;
    const st = readStore();
    if (st?.job_id) return resume(st.job_id);
    return refreshHealth();
  }

  async function refreshHealth() {
    controls();
    setReason('Checking the run service…');
    const r = await request('/api/health');
    const st = readStore();
    if (!r.ok) {
      setState('error', 'Unreachable', 'The run service could not be reached.');
      setReason(`${r.timeout ? 'The health check timed out.' : 'A network error prevented contacting the run service.'} Check your connection and try again.`, true);
      return controls({recheck: refreshHealth});
    }
    if (r.status === 503) {
      setState('idle', 'Disabled', 'The run service is currently disabled.');
      setReason(withMessage('The operator has paused new runs.', r.data), true);
      return controls({recheck: refreshHealth});
    }
    const d = obj(r.data);
    if (r.status < 200 || r.status > 299 || !d) {
      setState('error', 'Unavailable', 'The run service health check failed.');
      setReason(`The health check returned ${r.status >= 200 && r.status < 300 ? 'an unreadable body' : `HTTP ${r.status}`}.`, true);
      return controls({recheck: refreshHealth});
    }
    const active = str(d.active_run_id);
    $('serviceMeta').replaceChildren(...meta([
      ['Run service', d.available === true ? 'available' : 'not accepting runs'],
      ['Remaining runs', finite(d.remaining_runs) ? String(d.remaining_runs) : '—'],
      ['Run in progress', active ? 'yes' : 'none'],
      ['Scope', str(d.scope) ? clip(d.scope, 160) : '—'],
    ]));
    if (active && st?.job_id === active) return resume(active);
    const pendingRequest = st?.request_id && !st.job_id;
    if (active) {
      setState('wait', 'Busy', 'Another run is in progress.');
      setReason(withMessage('Only one cycle runs at a time. Check again in a few minutes.', d));
      return controls({recheck: refreshHealth});
    }
    if (finite(d.remaining_runs) && d.remaining_runs <= 0) {
      setState('wait', 'Quota used', 'The run quota for this demo is used up.');
      setReason(withMessage('No further runs can be started.', d));
      return controls({recheck: refreshHealth});
    }
    if (d.available !== true) {
      const cooling = /cool/i.test(str(d.message) || '');
      setState('wait', cooling ? 'Cooldown' : 'Unavailable', cooling ? 'The service is cooling down between runs.' : 'The run service is not accepting runs right now.');
      setReason(withMessage('Check again shortly.', d));
      return controls({recheck: refreshHealth});
    }
    if (!newUuid()) {
      setState('error', 'Unsupported', 'This browser cannot create a secure request ID.');
      setReason('A browser with the Web Crypto API is required to start a run.', true);
      return controls();
    }
    setState('idle', 'Ready', pendingRequest ? 'An unconfirmed start request from this tab can be resent.' : 'No run started from this tab.');
    setReason(withMessage(pendingRequest
      ? 'Pressing the button resends the same request ID, so the server cannot start a duplicate run.'
      : 'Pressing the button sends one start request. The cycle takes several minutes.', d));
    return controls({start:true, startLabel: pendingRequest ? 'Resend start request' : 'Start new research loop'});
  }

  // ---------- start ----------
  async function start() {
    if (state.busy || !state.origin) return;
    let st = readStore();
    if (st?.job_id) return resume(st.job_id);
    if (!st?.request_id) {
      const id = newUuid();
      if (!id) return;
      st = {request_id:id, job_id:null, saved_at:new Date().toISOString()};
      writeStore(st);
    }
    state.busy = true; state.startedHere = true;
    controls();
    setState('active', 'Sending', 'Sending one start request…');
    setReason('Waiting for the server to accept the request.');
    const r = await request('/api/runs', 'POST', JSON.stringify({request_id: st.request_id}));
    state.busy = false;
    const d = obj(r.data);
    if (!r.ok || r.status >= 500 && r.status !== 503) {
      // Outcome unknown: keep the request ID so a retry is idempotent.
      setState('error', r.ok ? 'Server error' : 'Network error', r.ok ? `The start request failed with HTTP ${r.status}.` : 'The start request could not be confirmed.');
      setReason('Pressing the button again resends the same request ID, so no duplicate run is created.', true);
      return controls({start:true, startLabel:'Resend start request'});
    }
    if (r.status >= 200 && r.status <= 299) {
      if (!d || !UUID_RE.test(d.id || '')) {
        setState('error', 'Unexpected reply', 'The server accepted the request but returned no valid run ID.');
        setReason('Pressing the button again resends the same request ID.', true);
        return controls({start:true, startLabel:'Resend start request'});
      }
      writeStore({...st, job_id:d.id, accepted_at:new Date().toISOString()});
      return resume(d.id);
    }
    clearStore(); // definite rejection: the next press uses a fresh ID
    if (r.status === 409) {
      setState('wait', 'Busy', 'Another run is in progress; your request was not started.');
      setReason(withMessage('Only one cycle runs at a time. Check again in a few minutes.', d));
    } else if (r.status === 429) {
      const text = `${str(d?.code) || ''} ${str(d?.reason) || ''} ${serverMessage(d) || ''}`;
      const cooling = /cool|wait|retry/i.test(text), quota = /quota|limit|remaining|exhaust/i.test(text);
      setState('wait', cooling ? 'Cooldown' : quota ? 'Quota used' : 'Rate limited',
        cooling ? 'The service is cooling down between runs; your request was not started.' : quota ? 'The run quota is used up; your request was not started.' : 'Too many runs recently (quota or cooldown); your request was not started.');
      setReason(withMessage(`Try again later.${retryAfterText(r.retryAfter)}`, d));
    } else if (r.status === 503) {
      setState('idle', 'Disabled', 'The run service is currently disabled; your request was not started.');
      setReason(withMessage('The operator has paused new runs.', d), true);
    } else if (r.status === 400) {
      setState('error', 'Rejected', 'The server rejected the start request as malformed.');
      setReason('Reload the page and try again. A new request ID will be used.', true);
    } else {
      setState('error', 'Rejected', `The start request was refused with HTTP ${r.status}.`);
      setReason(withMessage('Your request was not started.', d), true);
    }
    return controls({recheck: refreshHealth});
  }

  // ---------- polling ----------
  function resume(id) {
    state.jobId = id; state.failures = 0; state.resultTries = 0;
    controls();
    setReason('A run from this tab is in progress. This page checks its status every 4 seconds; you can leave it open or reload it.');
    setState('active', 'Checking', 'Reading the status of your run…');
    poll();
  }

  function backoff(text) {
    state.failures += 1;
    const ms = Math.min(POLL_MS * 2 ** (state.failures - 1), MAX_BACKOFF_MS);
    setState('wait', 'Reconnecting', `${text} Retrying in ${Math.round(ms / 1000)} s. The run continues on the server.`);
    schedule(poll, ms);
  }

  async function poll() {
    const id = state.jobId;
    const r = await request(`/api/runs/${encodeURIComponent(id)}`);
    if (id !== state.jobId) return;
    if (!r.ok) return backoff(r.timeout ? 'The status request timed out.' : 'The status request failed (network error).');
    if (r.status === 404) {
      clearStore();
      setState('error', 'Not found', 'The server no longer knows this run.');
      setReason('It may have expired. You can set up another run.', true);
      return controls({newRun:true});
    }
    const d = obj(r.data);
    if (r.status < 200 || r.status > 299 || !d) return backoff(`The status request returned ${r.status >= 200 && r.status < 300 ? 'an unreadable body' : `HTTP ${r.status}`}.`);
    if (d.id != null && d.id !== id) {
      setState('error', 'Mismatch', 'The server returned the status of a different run.');
      return controls({recheck: () => resume(id)});
    }
    state.failures = 0;
    renderStatus(d, id);
    const status = d.status;
    if (status === 'completed') return fetchResult(id);
    if (status === 'failed') {
      writeStore({...readStore(), status:'failed'});
      setState('error', 'Failed', str(d.error) ? `The run failed: ${clip(d.error)}` : 'The run failed.');
      setReason('No result is shown for a failed run. You can set up another run if the quota allows.', true);
      return controls({newRun:true});
    }
    if (status === 'queued') setState('wait', 'Queued', 'Your run is queued on the server.');
    else if (status === 'running') setState('active', 'Running', str(d.phase) ? `Running · phase: ${clip(d.phase, 120)}` : 'Running.');
    else setState('wait', 'Unknown state', `The server reported status “${clip(show(status), 60)}”.`);
    schedule(poll, POLL_MS);
  }

  function renderStatus(d, id) {
    const ver = obj(d.verification) ? obj(d.verification).status : d.verification;
    $('statusMeta').hidden = false;
    $('statusMeta').replaceChildren(...meta([
      ['Run ID', code(id)],
      ['Status', show(str(d.status))],
      ['Ledger phase', str(d.phase) ? clip(d.phase, 120) : '—'],
      ['Plans recorded', count(d.plans)],
      ['Experiments recorded', count(d.experiments)],
      ['Interpretations recorded', count(d.updates)],
      ['Verification (server-reported)', str(ver) ? clip(ver, 60) : 'not yet reported'],
      ['Created', d.created_at ? time(d.created_at) : '—'],
      ['Last update (server)', d.updated_at ? time(d.updated_at) : '—'],
      ['Last checked (this browser)', time(new Date().toISOString())],
    ]));
    // Only a hypothesis the server explicitly reports; plan contents stay hidden until verified.
    const lastPlan = arr(d.plans).filter(obj).at(-1);
    const hyp = str(d.latest_hypothesis) || str(d.hypothesis) || str(lastPlan?.hypothesis);
    $('hypothesisBox').hidden = !hyp;
    if (hyp && $('hypothesisText').textContent !== hyp) $('hypothesisText').textContent = clip(hyp, 2000);
  }

  // ---------- result ----------
  async function fetchResult(id) {
    setState('active', 'Completed', 'The run completed. Loading its verified result…');
    const r = await request(`/api/runs/${encodeURIComponent(id)}/result`);
    if (id !== state.jobId) return;
    const notReady = !r.ok || r.status === 404 || r.status === 409 || r.status === 425 || r.status >= 500;
    if (notReady) {
      state.resultTries += 1;
      if (state.resultTries <= RESULT_RETRIES) {
        setState('wait', 'Completed', 'The run completed; its result is not available yet. Retrying…');
        return schedule(() => fetchResult(id), Math.min(POLL_MS * state.resultTries, MAX_BACKOFF_MS));
      }
      setState('error', 'Result unavailable', `The result could not be loaded${r.ok ? ` (HTTP ${r.status})` : ' (network error)'}.`);
      return controls({recheck: () => { state.resultTries = 0; fetchResult(id); }, newRun:true});
    }
    const d = obj(r.data);
    if (r.status < 200 || r.status > 299 || !d) {
      setState('error', 'Result unavailable', `The result request returned ${r.status >= 200 && r.status < 300 ? 'an unreadable body' : `HTTP ${r.status}`}.`);
      return controls({recheck: () => { state.resultTries = 0; fetchResult(id); }, newRun:true});
    }
    const sdkStatus = obj(d.sdk)?.status, verStatus = obj(d.verification)?.status;
    if (d.schema_version !== 1 || d.project !== 'WaffleBench' || sdkStatus !== 'completed' || verStatus !== 'passed') {
      setState('error', 'Not verified', `The result is not shown: session status ${show(str(sdkStatus) ?? 'missing')}, verification status ${show(str(verStatus) ?? 'missing')}, schema ${show(d.schema_version)}.`);
      setReason('Only a completed session with passed verification is displayed.', true);
      return controls({newRun:true});
    }
    try { renderResult(d); }
    catch (error) {
      console.error('Discovery run render:', error);
      setState('error', 'Display error', 'The verified result does not have the expected structure.');
      return controls({newRun:true});
    }
    state.bytes = r.bytes;
    writeStore({...readStore(), status:'completed'});
    $('download').disabled = false;
    $('resultSection').hidden = false;
    setState('done', 'Verified', 'Completed · session completed and verification passed. The result is shown below.');
    setReason('This run is finished. You can download the exact JSON or set up another run if the quota allows.');
    controls({newRun:true});
    if (state.startedHere) $('resultTitle').focus();
  }

  function renderResult(d) {
    const sdk = obj(d.sdk) || {};
    $('resultMeta').replaceChildren(...meta([
      ['Run', state.jobId], ['Session', sdk.session_id], ['Model', sdk.model], ['Harness', sdk.harness],
      ['Cycle', obj(d.closed)?.status ? `closed · ${obj(d.closed).status}` : null],
    ]));
    $('resultQuestion').textContent = str(d.question) ? d.question : '—';
    const plans = arr(d.plans).filter(obj), results = arr(d.results).filter(obj), updates = arr(d.updates).filter(obj);
    const sourceShas = new Set(arr(d.sources).map(s => obj(s)?.sha256).filter(str));
    const out = [];
    if (plans.length !== 2) out.push(h('p', {class:'warn', role:'note'}, `The result contains ${plans.length} plan(s); this cycle is expected to contain exactly 2. All recorded plans are shown.`));
    if (!plans.length) out.push(h('div', {class:'empty'}, h('strong', null, 'No plans recorded'), 'The result contains no experiment plans.'));
    plans.forEach((p, i) => {
      const r = results.find(x => x.plan_id != null && x.plan_id === p.plan_id) || null;
      const u = r ? updates.find(x => x.result_id != null && x.result_id === r.result_id) || null : null;
      // A proposal made at this update counts as later executed only if a later plan's result ran that test.
      const next = str(u?.next_experiment);
      const later = next ? results.find(x => str(x.test_id) && plans.findIndex(pl => pl.plan_id === x.plan_id) > i && new RegExp(`\\b${escapeRe(x.test_id)}\\b`).test(next)) : null;
      out.push(card(p, r, u, i, i === plans.length - 1, sourceShas, later));
    });
    const orphan = results.filter(r => !plans.some(p => p.plan_id === r.plan_id));
    if (orphan.length) out.push(h('p', {class:'warn', role:'note'}, `${orphan.length} recorded result(s) reference no plan in this file: `, orphan.map(r => show(r.result_id)).join(', ')));
    $('resultCards').replaceChildren(...out);
    renderVerification(d);
  }

  function step(title, tag, body, extraClass) {
    return h('div', {class:`exp-step${extraClass ? ` ${extraClass}` : ''}`}, h('h4', null, title, tag), h('div', null, body));
  }
  const para = (label, v) => h('p', null, label ? h('span', {class:'sub'}, `${label}: `) : null, show(str(v) ?? (v == null || typeof v === 'object' ? null : v)));

  // Arbitrary nesting: every leaf becomes one "path → value" row; the full JSON stays available.
  function flatten(v, path, out, depth) {
    if (out.length >= MAX_VALUE_ROWS) return;
    if (v === null || typeof v !== 'object') { out.push([path || '(value)', v]); return; }
    if (depth > 12) { out.push([path, json(v)]); return; }
    const entries = Array.isArray(v) ? v.map((x, i) => [`[${i}]`, x]) : Object.entries(v);
    if (!entries.length) out.push([path || '(value)', Array.isArray(v) ? '[]' : '{}']);
    for (const [k, x] of entries) flatten(x, path ? (k.startsWith('[') ? `${path}${k}` : `${path}.${k}`) : k, out, depth + 1);
  }
  const leaf = v => typeof v === 'number' ? (Number.isFinite(v) ? String(v) : 'non-finite') : v === null ? 'null' : String(v);
  function countLeaves(v, depth = 0) {
    if (v === null || typeof v !== 'object' || depth > 12) return 1;
    const xs = Array.isArray(v) ? v : Object.values(v);
    return xs.length ? xs.reduce((n, x) => n + countLeaves(x, depth + 1), 0) : 1;
  }

  function valuesBlock(values, label) {
    const rows = [];
    flatten(values, '', rows, 0);
    const total = countLeaves(values);
    return [
      rows.length ? h('div', {class:'table-scroll', tabindex:'0', role:'region', 'aria-label':label},
        h('table', {class:'data-table value-table'},
          h('thead', null, h('tr', null, h('th', {scope:'col'}, 'Field'), h('th', {scope:'col'}, 'Recorded value'))),
          h('tbody', null, rows.map(([k, v]) => h('tr', null, h('th', {scope:'row'}, k), h('td', {class: typeof v === 'number' ? 'num' : null}, leaf(v)))))))
        : h('p', null, '—'),
      total > rows.length ? h('p', {class:'value-note'}, `Showing the first ${rows.length} of ${total} fields; all fields are in the JSON below.`) : null,
      h('details', {class:'raw'}, h('summary', null, 'All recorded values as JSON'), h('pre', null, json(values))),
    ];
  }

  function card(p, r, u, i, isLast, sourceShas, later) {
    const cands = arr(p.candidates).filter(x => typeof x === 'string');
    const sel = p.selected_test_id;
    const steps = [];
    steps.push(step('Initial hypothesis', who('agent', 'Agent-authored'), [
      para(null, p.hypothesis),
      h('p', {class:'sub'}, 'Evidence cited: ', arr(p.evidence_result_ids).length ? arr(p.evidence_result_ids).map(show).join(', ') : 'none (first plan or none recorded)'),
    ]));
    steps.push(step('Competing tests', who('agent', 'Agent-authored from fixed catalog'), [
      cands.length ? h('ul', {class:'cand-list', 'aria-label':'Candidate catalog test IDs'}, cands.map(c => h('li', {class: c === sel ? 'is-chosen' : null}, c, c === sel ? h('small', null, 'chosen') : null))) : h('p', null, '—'),
      cands.length < 2 ? h('p', {class:'warn', role:'note'}, `Only ${cands.length} candidate test(s) recorded; at least 2 competing tests are expected.`) : null,
    ]));
    steps.push(step('Chosen study and rationale', who('agent', 'Agent-authored'), [
      h('p', null, h('span', {class:'sub'}, 'Selected test: '), code(sel)),
      para('Reason', p.reason),
      para('Expected learning', p.expected_learning),
      h('p', {class:'integrity'}, 'Selected test is among candidates: ', mark(str(sel) ? cands.includes(sel) : null)),
    ]));
    if (r) {
      const elapsed = finite(r.elapsed_seconds) ? r.elapsed_seconds : finite(r.elapsed_s) ? r.elapsed_s : null;
      steps.push(step('Actual result', who('det', 'Deterministic computation'), [
        obj(r.values) || Array.isArray(r.values) ? valuesBlock(r.values, `Recorded values for result ${show(r.result_id)}`) : h('p', null, '— No values recorded.'),
        str(r.evaluation_label) ? h('p', {class:'sub'}, `Evaluation label: ${r.evaluation_label}`) : null,
        h('p', {class:'integrity'}, 'Result ', code(r.result_id), ' · test ', code(r.test_id),
          ' · elapsed ', elapsed != null ? `${elapsed} s (recorded wall-clock, not a speed claim)` : '—',
          typeof r.new_heldout_gain === 'boolean' ? ` · new hold-out gain: ${r.new_heldout_gain}` : ''),
        h('p', {class:'integrity'}, 'Test matches selected study: ', mark(str(r.test_id) && str(sel) ? r.test_id === sel : null),
          ' · Source hash listed in sources: ', mark(str(r.source_sha256) ? sourceShas.has(r.source_sha256) : null)),
      ]));
    } else {
      steps.push(step('Actual result', who('det', 'Deterministic computation'), h('div', {class:'empty'}, h('strong', null, 'No result recorded for this plan'), 'No measured values are shown.')));
    }
    if (u) {
      steps.push(step('Result-bound interpretation', who('agent', 'Agent-authored'), [para(null, u.interpretation), para('Next hypothesis', u.next_hypothesis)]));
      const tag = later ? 'Proposal at this update · later executed' : isLast ? 'Final proposal · not executed' : 'Proposed · not executed';
      steps.push(step('Next proposed experiment', who('prop', tag), [
        para(null, u.next_experiment),
        later
          ? h('p', {class:'sub'}, 'This was unexecuted when the update was recorded. A later plan selected ', code(later.test_id), ' and executed it as ', code(later.result_id), '; see the next experiment card.')
          : h('p', {class:'sub'}, isLast ? 'This is the cycle’s final prospective proposal. It was not run and has no measured result.' : 'This is a proposal only. It was not run and has no measured result.'),
      ], 'proposed'));
    } else {
      steps.push(step('Result-bound interpretation', who('agent', 'Agent-authored'), h('p', null, '— No interpretation recorded for this result.')));
    }
    return h('article', {class:'exp-card', 'aria-labelledby':`runExp${i}`},
      h('header', null, h('h3', {id:`runExp${i}`}, `Experiment ${i + 1}`), h('span', {class:'ids'}, 'Plan ', code(p.plan_id))),
      steps);
  }

  function checkRows(checks) {
    if (Array.isArray(checks)) return checks.map((c, i) => {
      if (typeof c === 'string') return [c, null, null];
      const o = obj(c) || {};
      const st = o.status ?? (o.passed === true || o.ok === true ? 'passed' : o.passed === false || o.ok === false ? 'failed' : null);
      return [o.name ?? o.id ?? o.check ?? `Check ${i + 1}`, st, o.detail ?? o.message ?? null];
    });
    const o = obj(checks);
    if (!o) return [];
    return Object.entries(o).map(([k, v]) => {
      if (typeof v === 'boolean') return [k, v ? 'passed' : 'failed', null];
      const vo = obj(v);
      if (vo) return [k, vo.status ?? (vo.passed === true ? 'passed' : vo.passed === false ? 'failed' : null), vo.detail ?? vo.message ?? json(vo)];
      return [k, typeof v === 'string' ? v : null, typeof v === 'string' ? null : show(v)];
    });
  }

  function renderVerification(d) {
    const sdk = obj(d.sdk) || {}, ver = obj(d.verification) || {};
    const rows = checkRows(ver.checks), sources = arr(d.sources).filter(obj);
    const cell = v => typeof v === 'object' && v !== null ? json(v) : show(v);
    const okRe = /^(passed|pass|ok|completed|match)$/i, badRe = /^(failed|fail|error|mismatch)$/i;
    $('resultVerification').replaceChildren(
      h('h3', null, 'Session and ledger verification'),
      receipt([['Session ID', code(sdk.session_id)], ['Session status', code(sdk.status)], ['Verification status', code(ver.status)], ['Checked at', ver.checked_at ? time(ver.checked_at) : '—']]),
      h('div', {class:'ver-tables'},
        rows.length ? h('div', {class:'table-scroll', tabindex:'0', role:'region', 'aria-label':'Verification checks'},
          h('table', {class:'data-table'}, h('thead', null, h('tr', null, h('th', {scope:'col'}, 'Check'), h('th', {scope:'col'}, 'Status'), h('th', {scope:'col'}, 'Detail'))),
            h('tbody', null, rows.map(([n, s, det]) => h('tr', null, h('th', {scope:'row'}, cell(n)), h('td', {class: okRe.test(s) ? 'ok' : badRe.test(s) ? 'bad' : null}, cell(s)), h('td', {class:'reason'}, cell(det)))))))
          : h('div', {class:'empty'}, h('strong', null, 'No individual checks listed'), 'Only the overall verification status is recorded.'),
        sources.length ? h('div', {class:'table-scroll', tabindex:'0', role:'region', 'aria-label':'Source files and hashes'},
          h('table', {class:'data-table'}, h('thead', null, h('tr', null, h('th', {scope:'col'}, 'Source'), h('th', {scope:'col'}, 'SHA-256'))),
            h('tbody', null, sources.map(s => h('tr', null, h('th', {scope:'row'}, show(s.path)), h('td', {class:'mono-id'}, show(s.sha256)))))))
          : null));
  }

  // ---------- actions ----------
  function download() {
    if (!state.bytes) return;
    const url = URL.createObjectURL(new Blob([state.bytes], {type:'application/json'}));
    const a = h('a', {href:url, download:`discovery-run-${state.jobId || 'result'}.json`});
    document.body.append(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  function newRun() {
    clearTimeout(state.timer);
    clearStore();
    Object.assign(state, {jobId:null, bytes:null, startedHere:false, failures:0, resultTries:0});
    $('download').disabled = true;
    $('resultSection').hidden = true;
    $('statusMeta').hidden = true;
    $('hypothesisBox').hidden = true;
    setState('idle', 'Idle', 'No run started from this tab.');
    refreshHealth();
  }

  $('startRun').addEventListener('click', start);
  $('recheck').addEventListener('click', () => { if (state.recheck) state.recheck(); });
  $('newRun').addEventListener('click', newRun);
  $('download').addEventListener('click', download);
  window.__discoveryRun = {state, parseConfig};
  init();
})();
